custom_fields.board:
[[[
  const date = new Date();
  const weekday = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
  const tomorrow = new Date(date);
  tomorrow.setDate(date.getDate() + 1);
  const dateLabel = date.toLocaleDateString([], { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).toUpperCase();
  const eventLines = (entity) => (states[entity]?.state || '').split('\n').filter(Boolean).map((line) => {
    const [title, when] = line.split('||');
    return { title: title || 'Untitled', when: when || 'All day' };
  });
  const rows = (events) => events.slice(0, 4).map((event) => `<div class="event"><span class="event-time">${event.when}</span><span>${event.title}</span></div>`).join('') || '<div class="empty">No events scheduled</div>';
  const today = eventLines('input_text.calendar_today_events');
  const tomorrowEvents = eventLines(`input_text.calendar_${weekday[tomorrow.getDay()]}_events`);
  const rawCondition = states['input_text.e_ink_weather_condition']?.state || '';
  const condition = ({ sunny: 'Sunny', clear: 'Clear', 'clear-night': 'Clear', partlycloudy: 'Partly Cloudy', 'partly-cloudy': 'Partly Cloudy', cloudy: 'Cloudy', rainy: 'Rainy', pouring: 'Rainy', snowy: 'Snowy', 'snowy-rainy': 'Snow' })[rawCondition.toLowerCase()] || rawCondition || 'Forecast';
  const high = states['input_text.e_ink_weather_high']?.state || '--°';
  const low = states['input_text.e_ink_weather_low']?.state || '--°';
  const sun = states['sun.sun'];
  const formatTime = (value) => value ? new Date(value).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) : '--:--';
  const sunrise = formatTime(sun?.attributes?.next_rising);
  const sunset = formatTime(sun?.attributes?.next_setting);
  return `<div class="board">
    <div class="date">${dateLabel}</div>
    <div class="today-events">${rows(today)}</div>
    <div class="tomorrow-events">${rows(tomorrowEvents)}</div>
    <div class="sunrise-time">${sunrise}</div>
    <div class="sunset-time">${sunset}</div>
    <div class="weather-condition">${condition}</div>
    <div class="weather-high">${high}</div>
    <div class="weather-low">${low}</div>
  </div>`;
]]]

cards.extra_styles:
.board {
  width: 800px;
  height: 480px;
  position: relative;
  overflow: hidden;
  background: url('/local/housevoice/assets/references/e-ink-background-8.png') 0 0 / 800px 480px no-repeat;
  color: #10274a;
  font-family: Georgia, 'Times New Roman', serif;
}
.date {
  position: absolute;
  left: 237px;
  top: 132px;
  width: 340px;
  color: #10274a;
  font-size: 16px;
  letter-spacing: 1.5px;
  text-align: center;
  white-space: nowrap;
}
.today-events,
.tomorrow-events {
  position: absolute;
  top: 223px;
  height: 118px;
  overflow: hidden;
  font-size: 11.5px;
  line-height: 1.3;
}
.today-events {
  left: 237px;
  width: 165px;
}
